import{_ as t,o as n,c as e,a6 as s}from"./chunks/framework.BBIckNDn.js";const c=JSON.parse('{"title":"品質のための道具 — 静的解析・サニタイザ・警告レベル・CI","description":"","frontmatter":{"title":"品質のための道具 — 静的解析・サニタイザ・警告レベル・CI","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"バグを「実行して踏む」前に機械に見つけさせる4つの層です。検出が早いほど安い(コンパイル時 < テスト実行時 < QA < ユーザー環境)という原則で並べます。 コンパイラの警告は「合法だが怪しいコード」の検出器です。"}},"headers":[],"relativePath":"tools/build/debugging-and-analysis.md","filePath":"tools/build/debugging-and-analysis.md"}'),i={name:"tools/build/debugging-and-analysis.md"};function l(d,a,r,o,p,h){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="品質のための道具-—-静的解析・サニタイザ・警告レベル・ci" tabindex="-1">品質のための道具 — 静的解析・サニタイザ・警告レベル・CI <a class="header-anchor" href="#品質のための道具-—-静的解析・サニタイザ・警告レベル・ci" aria-label="Permalink to &quot;品質のための道具 — 静的解析・サニタイザ・警告レベル・CI&quot;">​</a></h1><p>バグを「実行して踏む」前に機械に見つけさせる4つの層です。<strong>検出が早いほど安い</strong>(コンパイル時 &lt; テスト実行時 &lt; QA &lt; ユーザー環境)という原則で並べます。</p><h2 id="_1-警告レベル-コンパイル時・無料" tabindex="-1">1. 警告レベル(コンパイル時・無料) <a class="header-anchor" href="#_1-警告レベル-コンパイル時・無料" aria-label="Permalink to &quot;1. 警告レベル(コンパイル時・無料)&quot;">​</a></h2><p>コンパイラの警告は「合法だが怪しいコード」の検出器です。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GCC/Clang: -Wall -Wextra          # 「Wallで全部」ではない点に注意(歴史的な名前)</span></span>
<span class="line"><span>           -Wconversion(縮小変換) -Wshadow(変数の隠蔽)などを追加</span></span>
<span class="line"><span>MSVC:      /W4                    # /Wallはシステムヘッダーまで鳴るので/W4が実用上限</span></span>
<span class="line"><span>共通:       -Werror | /WX          # 警告をエラー化(CIでは必須級)</span></span></code></pre></div><ul><li>検出例: 未初期化の可能性、符号比較、到達しないコード、enum switchの網羅漏れ(→ <a href="/study/languages/cpp/enums-and-namespaces.html">enum</a>)、<a href="/study/languages/cpp/undefined-behavior.html">UB</a>の前兆多数</li><li><strong>プロジェクト開始時に最大化して-Werror</strong>が鉄則。途中から上げると数千件のノイズで詰む。サードパーティのヘッダーは警告抑制の対象外にする(SYSTEMインクルード扱い)</li></ul><h2 id="_2-静的解析-コンパイル時-α" tabindex="-1">2. 静的解析(コンパイル時+α) <a class="header-anchor" href="#_2-静的解析-コンパイル時-α" aria-label="Permalink to &quot;2. 静的解析(コンパイル時+α)&quot;">​</a></h2><p>コードを実行せず、データフロー・パス解析でバグを探すツール。警告より深い(関数間・パス依存の解析)。</p><ul><li><strong>clang-tidy</strong>: 定番。バグ検出+モダン化提案(「生ループをrange-forに」等)+命名規則。CMakeと統合可能</li><li>MSVCの <code>/analyze</code>、PVS-Studio(ゲーム業界で採用例が多い商用)、Cppcheck</li><li>検出例: nullチェック漏れのパス、リークするパス、危険なキャスト、<a href="/study/languages/cpp/ctor-dtor-copy-move.html">コピーの見落とし</a></li><li>誤検出(false positive)とは付き合い方が必要: 抑制コメントを乱発せず、ルールセットをプロジェクトに合わせて絞る</li></ul><h2 id="_3-サニタイザ-実行時・開発ビルドの標準装備" tabindex="-1">3. サニタイザ(実行時・開発ビルドの標準装備) <a class="header-anchor" href="#_3-サニタイザ-実行時・開発ビルドの標準装備" aria-label="Permalink to &quot;3. サニタイザ(実行時・開発ビルドの標準装備)&quot;">​</a></h2><p>コンパイラがチェックコードを織り込み、<strong>実行中に</strong>UB・メモリバグを捕まえる仕組み(→ <a href="/study/runtime/memory/memory-bugs.html">メモリバグ図鑑</a>との対応)。</p><table tabindex="0"><thead><tr><th>サニタイザ</th><th>捕まえるもの</th><th>速度低下(目安)</th></tr></thead><tbody><tr><td><strong>ASan</strong> (Address)</td><td>範囲外・UAF・double free・リーク</td><td>~2倍</td></tr><tr><td><strong>UBSan</strong> (UndefinedBehavior)</td><td>符号オーバーフロー、null参照外し、不正シフト等</td><td>軽微</td></tr><tr><td><strong>TSan</strong> (Thread)</td><td>データ競合(→ <a href="/study/runtime/memory/concurrency-bugs.html">並行バグ</a>)</td><td>5〜15倍</td></tr><tr><td>MSan (Memory)</td><td>未初期化読み取り(Clang/Linux限定)</td><td>3倍</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++ -fsanitize=address,undefined -g -O1 game.cpp    # ASan+UBSan併用が開発の定番</span></span>
<span class="line"><span>MSVC: /fsanitize=address(VS2019 16.9+)</span></span></code></pre></div><ul><li><strong>「たまに落ちる」を数週間追う vs ASanで一発</strong>——費用対効果はC++ツールで最大級。開発ビルドとCIテストに常設する</li><li>制約: Shippingには入れない(速度・メモリ)。プラットフォームにより対応差(本Wikiの検証環境MinGW GCC 9.2は非対応のため、記述はGCC/Clang/MSVCの公式ドキュメント準拠)</li></ul><h2 id="_4-ci-continuous-integration" tabindex="-1">4. CI (Continuous Integration) <a class="header-anchor" href="#_4-ci-continuous-integration" aria-label="Permalink to &quot;4. CI (Continuous Integration)&quot;">​</a></h2><p>push/PRのたびに機械がビルド+テスト+解析を回す仕組み(GitHub Actions、Jenkins等)。</p><p>ゲームC++プロジェクトの典型パイプライン:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push → [ビルド: MSVC + Clang 両方 / Debug + Shipping 両方]   ← 構成差・処理系差の早期検出</span></span>
<span class="line"><span>     → [ユニットテスト(ASan/UBSan付き)]</span></span>
<span class="line"><span>     → [clang-tidy / フォーマットチェック]</span></span>
<span class="line"><span>     → [(夜間)フルアセットビルド + 自動プレイテスト + TSan]</span></span></code></pre></div><ul><li>「自分のマシンでは通る」を殲滅するのが役割。<strong>ビルドを壊した変更を10分で検出</strong>できれば、修正コストは最小で済む</li><li>ゲーム特有: アセットビルドの検証、実機スモークテスト(起動して1分遊ぶbot)、性能リグレッション検出(フレーム時間の統計)</li></ul><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><table tabindex="0"><thead><tr><th>C#/Unity</th><th>C++</th></tr></thead><tbody><tr><td>コンパイラ警告+Roslyn Analyzer</td><td>警告+clang-tidy等</td></tr><tr><td>(言語仕様で大半のUBが例外化)</td><td>サニタイザで後付け検出</td></tr><tr><td>Unity Test Framework + Cloud Build</td><td>ユニットテスト+CI</td></tr></tbody></table><p>C#は言語がチェックを内蔵しているぶん道具が少なくて済んでいました。C++は<strong>チェックをツールで外付けする文化</strong>——道具を入れないC++開発は、シートベルトなしの運転に近い、という感覚を持つのが正解です。</p><h2 id="実務指針-導入順" tabindex="-1">実務指針(導入順) <a class="header-anchor" href="#実務指針-導入順" aria-label="Permalink to &quot;実務指針(導入順)&quot;">​</a></h2><ol><li>警告最大化+Werror(初日)</li><li>CIで2コンパイラ×2構成ビルド(最初の週)</li><li>テストにASan/UBSan(テストを書き始めたら即)</li><li>clang-tidy(ルールを絞って段階導入)</li><li>TSan・自動プレイテスト(並行コード・規模が出てきたら)</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「検出が早いほど安い」の4段階を言えますか。</li><li>ASanが劇的に有効なバグの種類は?(第7部のバグ図鑑と対応させて)</li><li>CIで「2コンパイラ×2構成」を回す理由は?</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>samples/ の任意のサンプルに意図的な範囲外アクセスを仕込み、(a) 警告で捕まるか、(b) 手元の環境でASanが使えるなら検出メッセージ(確保・解放・使用の3スタックトレース)を観察してください。使えない環境では、MSVCの/RTCやat()での代替検出を試してください。</p><hr><p>前: <a href="/study/tools/build/build-speed.html">ビルド時間</a> | <a href="/study/tools/build/">カテゴリ目次</a> | 次: <a href="/study/tools/build/link-errors.html">リンクエラー</a></p>`,30)])])}const g=t(i,[["render",l]]);export{c as __pageData,g as default};
